const express = require('express');
const app = express();
const server = app.listen(5004);

const gracefulShutdown = (signal) => {
    console.log(`Received ${signal}. Shutting down Express server...`);
    server.close(() => {
        console.log('All HTTP connections closed cleanly.');
        process.exit(0);
    });

    // Force shutdown after 10 seconds if connections hang
    setTimeout(() => {
        console.error('Forced shutdown due to timeout.');
        process.exit(1);
    }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));

const express = require('express');
const app = express();
app.use(express.json());

// 1. Auth Middleware
const authGuard = (req, res, next) => {
    const token = req.headers.authorization?.split(' ')[1];
    if (token === 'valid_jwt') {
        req.user = { id: 1, role: 'author' };
        return next();
    }
    res.status(401).json({ error: 'Unauthorized' });
};

// 2. Posts Modular Router
const postsRouter = express.Router();
const posts = [];

postsRouter.get('/', (req, res) => res.json(posts));
postsRouter.post('/', authGuard, (req, res) => {
    const { title, content } = req.body;
    if (!title || !content) return res.status(400).json({ error: 'Title and content required' });
    const post = { id: Date.now(), title, content, authorId: req.user.id };
    posts.push(post);
    res.status(201).json(post);
});

app.use('/api/v1/posts', postsRouter);

// 3. Centralized Error Handler
app.use((err, req, res, next) => {
    res.status(err.status || 500).json({ error: err.message || 'Server Error' });
});

app.listen(5005, () => console.log('Blog API Engine running on port 5005'));
